  KB.evidenceById = {};
  KB.applyEvidence = function () {
    KB.evidenceById = Object.fromEntries(EV.map(e => [e.evidence_id, e]));
    for (const r of KB.relations) { r.ev = []; r.draft = true; delete r.evidence_partial; }
    const cand = {};
    for (const e of EV) for (const d of e.diseases) for (const f of e.findings) {
      if (!f.feature_id) continue;
      const fdef = KB.feature[f.feature_id];
      const rels = (KB.relByDisease[d] || []).filter(r => r.f === f.feature_id && (
        (!fdef.values) ? true                                            // 二値 feature: そのまま一致
        : (f.values && r.values) ? f.values.some(v => r.values.includes(v)) // 値集合あり: 値の重なりが必要
        : (!f.values && !r.values)));                                     // 双方とも値指定なし（例: 部位を問わない腹痛）
      for (const r of rels) { const k = d + '|' + r.f + '|' + (r.values || []).join(','); (cand[k] = cand[k] || []).push({ e, f, r }); }
    }
    for (const k in cand) {
      const all = cand[k]; const r = all[0].r;
      for (const x of all) if (!r.ev.includes(x.e.evidence_id)) r.ev.push(x.e.evidence_id);
      const usable = all.filter(x => !x.f.ref_only && !x.f.composite).sort((a, b) => (KB.populationRank(a.e.population) - KB.populationRank(b.e.population)) || ((b.e.n || 0) - (a.e.n || 0)));
      if (!usable.length) { r.evidence_partial = true; continue; }
      const best = usable[0];
      let sens = best.f.sens, spec = best.f.spec;
      if (sens != null && spec != null && sens > 0 && sens < 1 && spec > 0 && spec < 1) { r.sens = sens; r.spec = spec; r.draft = false; r.evidence_note = best.f.note || ''; r.evidence_best = best.e.evidence_id; }
      else if (sens != null && sens > 0 && sens < 1) { r.sens = sens; r.draft = 'partial'; r.evidence_note = best.f.note || ''; r.evidence_best = best.e.evidence_id; }
      else r.evidence_partial = true;
    }
    KB.evidenceCoverage = { total: KB.relations.length, with_values: KB.relations.filter(r => r.draft === false).length, partial: KB.relations.filter(r => r.draft === 'partial').length, with_ref: KB.relations.filter(r => r.ev.length).length, sources: EV.length, guidelines: KB.guidelines.length };
  };
  KB.applyEvidence();
